/// <reference path="./mxc-embedded.d.ts" />
/**
 * Runtime materialization of mxc's embedded FFI library for a COMPILED
 * boundless, where node_modules isn't on disk and the SDK can't find its own
 * native library. The `embedded.ts` importer (generated by
 * `scripts/build-mxc-runtime.ts`, gitignored) carries the library bytes via
 * Bun's `with { type: "file" }` embedding. This module writes them out to a
 * stable per-content-hash directory under `~/.bound/less/mxc-runtime/` and
 * points `MXC_FFI_DIR` at it, recreating the `<arch>/<name>` layout the SDK
 * resolver expects (`_mxcFfiCandidates` in the SDK unshifts `MXC_FFI_DIR` and
 * matches the per-arch subdir as well).
 *
 * v1's `run()`/`spawn()` path is pure FFI: the seatbelt/bubblewrap backend is
 * driven in-process through `libmxc_ffi.dylib`/`.so` loaded by koffi, so the
 * old `mxc-exec-mac` exec stub is no longer part of the execution path and is
 * not staged. koffi's own native `.node` rides into the compiled binary via
 * the native-addon staging in `scripts/build.ts`, not through this module.
 *
 * In a dev / source run the importer either carries the host library staged
 * at install time (in which case materializing is harmless and uniform) or is
 * empty (in which case this no-ops and the SDK self-resolves from
 * node_modules). Either way the SDK finds the library the same way in both modes.
 */
import { chmodSync, existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { dirname, join } from "node:path";
import { MXC_EMBEDDED_ASSETS, MXC_RUNTIME_HASH } from "../_mxc/embedded";

/** Mutable once-per-process latch for {@link ensureMxcRuntime}; tests pass their own. */
interface EnsureLatch {
	done: boolean;
}
const moduleLatch: EnsureLatch = { done: false };

/** Test-only injection seam for {@link ensureMxcRuntime}. Production passes nothing. */
export interface EnsureMxcRuntimeDeps {
	/** Isolated latch so a test exercises the body without tripping the module latch. */
	latch?: EnsureLatch;
	/** Override the embedded asset list (default: the generated importer). */
	assets?: ReadonlyArray<{ name: string; arch: string; executable: boolean; path: string }>;
	/** Root under which `<hash>/<arch>/<name>` is materialized (default: `~/.bound/less/mxc-runtime`). */
	baseDir?: string;
	/** Content-hash subdirectory (default: the generated hash). */
	hash?: string;
}

/**
 * Idempotently stage the embedded mxc FFI library and set `MXC_FFI_DIR`. Safe
 * to call on every spawn / availability check — the first call does the work,
 * the rest return immediately. Respects a pre-set `MXC_FFI_DIR` (operator
 * override) and no-ops when there are no embedded assets.
 *
 * The v1 FFI loader (`_mxcFfiCandidates`) unshifts `path.join(MXC_FFI_DIR,
 * libmxc_ffi.<ext>)` as its first candidate — the library file sits DIRECTLY
 * under `MXC_FFI_DIR`, with no `<arch>` subdir. We still materialize to
 * `<root>/<arch>/<name>` (so a future multi-arch importer stays unambiguous)
 * and point `MXC_FFI_DIR` at `<root>/<arch>` for the host arch.
 *
 * The `deps` seam is for tests only: production calls it with no argument, so
 * the latch, `MXC_FFI_DIR`, the embedded-asset list, and the home directory all
 * resolve as normal. A test passes an isolated latch, a temp base dir, and a
 * synthetic asset list to exercise the materialization path without touching
 * the real `~/.bound` or the once-per-process latch.
 */
export function ensureMxcRuntime(deps: EnsureMxcRuntimeDeps = {}): void {
	const latch = deps.latch ?? moduleLatch;
	if (latch.done) return;
	latch.done = true;

	// Operator already pointed mxc at an FFI directory — don't second-guess it.
	if (process.env.MXC_FFI_DIR) return;
	const assets = deps.assets ?? MXC_EMBEDDED_ASSETS;
	// Nothing embedded (empty importer): the SDK resolves from node_modules.
	if (!assets || assets.length === 0) return;

	const baseDir = deps.baseDir ?? join(homedir(), ".bound", "less", "mxc-runtime");
	const hash = deps.hash ?? MXC_RUNTIME_HASH;
	const root = join(baseDir, hash);
	// Track which arch dir to point MXC_FFI_DIR at (the one holding the host
	// arch's library). The SDK loader looks for <MXC_FFI_DIR>/libmxc_ffi.<ext>
	// directly, with no <arch> subdir, so FFI_DIR must be the arch-level dir.
	const hostArch = process.arch === "arm64" ? "arm64" : "x64";
	let ffiDir: string | undefined;
	for (const asset of assets) {
		const archDir = join(root, asset.arch);
		const dest = join(archDir, asset.name);
		if (asset.arch === hostArch) ffiDir = archDir;
		if (existsSync(dest)) continue;
		mkdirSync(dirname(dest), { recursive: true });
		writeFileSync(dest, readFileSync(asset.path));
		if (asset.executable) {
			try {
				chmodSync(dest, 0o755);
			} catch {
				// Best effort; a read-only FS or odd umask shouldn't be fatal here.
			}
		}
	}
	// Point the loader at the host arch's dir. If no asset matched the host arch
	// (an importer for a different arch), fall back to the materialization root
	// so a mismatch degrades to sandbox-unavailable rather than a wrong-arch load.
	process.env.MXC_FFI_DIR = ffiDir ?? root;
}
